// Generated by `cargo test` from the Rust types (src-tauri/src/settings.rs,
// `bindings`); don't edit. After changing them, run
// `ANOMP_WRITE_BINDINGS=1 cargo test bindings` in src-tauri.

export type AppSettings = { display: DisplaySettings, playback: PlaybackSettings, output: OutputSettings, visualizer: VisualizerSettings, };

/**
 * The settings, and the defaults a section can be reset to.
 */
export type SettingsPayload = { settings: AppSettings, defaults: AppSettings, };

/**
 * What the library's lists and pages show.
 */
export type DisplaySettings = { 
/**
 * What track lists show besides the title, in order.
 */
trackColumns: Array<TrackColumn>, 
/**
 * What an album's summary line says about its release, in order.
 */
albumFacts: Array<AlbumFact>, 
/**
 * Album descriptions and artist biographies (from Wikipedia).
 */
showDescriptions: boolean, };

export type TrackColumn = "trackNumber" | "artist" | "album" | "albumArtist" | "year" | "genre" | "duration" | "format" | "bitrate" | "sampleRate";

export type AlbumFact = "date" | "label" | "country" | "format" | "type";

export type PlaybackSettings = { replayGain: ReplayGainMode, 
/**
 * dB added to the ReplayGain tags' gains, -15 to 15.
 */
preamp: number, 
/**
 * dB for tracks without ReplayGain tags while it's on, -15 to 15.
 */
untaggedGain: number, 
/**
 * Lowers a track's gain so its tagged peak doesn't clip.
 */
preventClipping: boolean, };

export type ReplayGainMode = "off" | "track" | "album";

/**
 * Where the audio goes.
 */
export type OutputSettings = { 
/**
 * The output device's name; null for the system's default device.
 * When it isn't there, the default plays until it comes back.
 */
device: string | null, 
/**
 * Samples per block; null for the device's default.
 */
bufferSize: number | null, };

export type VisualizerSettings = { 
/**
 * The visualization's id (`app/src/lib/visualizer`); the frontend
 * shows its first one for an id it doesn't know.
 */
visualization: string, 
/**
 * Which albums the cover wall shows.
 */
coverBasis: CoverBasis, 
/**
 * Analyses a second, 10 to 120.
 */
frameRate: number, 
/**
 * Scales the spectrum, 0.25 to 4.
 */
sensitivity: number, 
/**
 * Colours from the current cover rather than the defaults.
 */
colorsFromCover: boolean, 
/**
 * Moves on to the next visualization this often; 0 never.
 */
cycleSeconds: number, };

export type CoverBasis = "year" | "artist";

/**
 * The output devices, and which one plays.
 */
export type OutputStatus = { 
/**
 * Every output device there is now.
 */
devices: Array<string>, 
/**
 * The open device, if any.
 */
current: DeviceInfo | null, 
/**
 * The settings name a device that isn't there: the default plays.
 */
chosenMissing: boolean, };

/**
 * The open output device's settings.
 */
export type DeviceInfo = { name: string, 
/**
 * Samples per block.
 */
bufferSize: number, defaultBufferSize: number, 
/**
 * What the device offers, smallest first.
 */
bufferSizes: Array<number>, 
/**
 * Hz.
 */
sampleRate: number, 
/**
 * Seconds from the player to the speakers.
 */
outputLatency: number, };

export type SortSettings = { 
/**
 * Never empty.
 */
rules: Array<SortRule>, 
/**
 * Words skipped at the start of artist names and album and track titles
 * when sorting (not when displaying), compared ignoring case and
 * accents. Empty turns this off.
 */
ignoredArticles: Array<string>, };

export type SortRule = { 
/**
 * Unique among the rules.
 */
id: string, name: string, levels: Array<Level>, trackOrder: Array<TrackKey>, 
/**
 * Missing in rules saved before it existed.
 */
albumOrder: AlbumOrder, };

/**
 * What tracks are grouped by at one level of a rule.
 */
export type Level = "albumArtist" | "artist" | "album" | "genre" | "year" | "folder";

/**
 * What tracks are sorted by within a group, in order of precedence. Ties
 * left after all of them fall back on the track id.
 */
export type TrackKey = "albumArtist" | "artist" | "album" | "year" | "discNumber" | "trackNumber" | "title" | "path";

/**
 * How albums are ordered where a rule lists them.
 */
export type AlbumOrder = "title" | "year";

export type MetadataSettings = { 
/**
 * Every source this version knows, in the order the UI lists them.
 */
sources: Array<SourceInfo>, settings: ServiceSettings, };

export type ServiceSettings = { 
/**
 * The switch for every online source; local ones are unaffected.
 */
online: boolean, 
/**
 * Look albums up in the background after each scan.
 */
autoMatch: boolean, 
/**
 * One entry per source, in `SourceId::ALL` order.
 */
sources: Array<SourceSettings>, 
/**
 * For each kind, every source that supplies it, in priority order.
 */
order: Record<MetadataKind, Array<SourceId>>, };

export type SourceSettings = { id: SourceId, enabled: boolean, 
/**
 * Whether its key is in the keychain (`keys`). Only `keys::set_key`
 * changes it: saving the settings keeps what was stored.
 */
hasKey: boolean, };

/**
 * What the UI shows about a source.
 */
export type SourceInfo = { id: SourceId, name: string, kinds: Array<MetadataKind>, 
/**
 * Contacts a service over the network, so it obeys the online switch.
 */
online: boolean, 
/**
 * Needs an API key or token from the user before it can be used.
 */
needsKey: boolean, 
/**
 * What the key is called, and where the user gets one.
 */
keyName: string | null, keyUrl: string | null, 
/**
 * On until the user turns it off.
 */
enabledByDefault: boolean, 
/**
 * Its details are kept in the library; otherwise only the match is,
 * and the details are fetched when shown (`metadata_release_details`).
 */
storesDetails: boolean, 
/**
 * Shown next to its data, linked to the page it came from, as its
 * terms require.
 */
credit: string | null, 
/**
 * Shown with the source in the settings, as its terms require.
 */
notice: string | null, 
/**
 * Another source it relies on (the Cover Art Archive needs a
 * MusicBrainz match, and Wikipedia a MusicBrainz artist or album).
 */
requires: SourceId | null, homepage: string | null, 
/**
 * The hosts it contacts, as `metadata-progress` names those that
 * can't be reached.
 */
hosts: Array<string>, };

/**
 * A metadata source. The serialized id is also what the `source` columns
 * of migration 003 store, so it must never change.
 */
export type SourceId = "embedded" | "folder" | "musicbrainz" | "cover-art-archive" | "wikipedia" | "discogs";

/**
 * A kind of data that sources supply.
 */
export type MetadataKind = "release" | "albumArt" | "artistInfo" | "albumInfo";
